test('actual second-mod ZIP installs, upgrades and preserves config and the main Ghost suite', async () => {
    const source=process.env.GHOST_PACK_FIXTURE;
    if (!source) throw new Error('GHOST_PACK_FIXTURE must point to the extracted final suite package');
    const base=await fs.mkdtemp(path.join(os.tmpdir(),'ghost-install-'));
    providePathImplementation(()=>path);
