    const game=Object.values(ecosystem.games).flatMap((g:any)=>g.r2modman || []).find((g:any)=>g.settingsIdentifier==='Valheim')!;
    const installer=new InstallRulePluginInstaller({gameName:'Valheim',rules:game.installRules,relativeFileExclusions:game.relativeFileExclusions});
    const mod=new ManifestV2();mod.setName('Ghost-GhostSmelterControl');mod.setAuthorName('Ghost');mod.setVersionNumber(new VersionNumber('1.0.0'));
    const profile={joinToProfilePath:(...p:string[])=>path.join(base,...p),getProfileName:()=> 'Fixture',getProfilePath:()=>base} as any;
