import { reactive } from 'vue';
import axios from 'axios';
import Game from '../model/game/Game';
import * as Db from '../r2mm/manager/PackageDexieStore';
import { GHOST_ORIGIN, GHOST_SMELTER_PACKAGE, normalizeGhostCatalog, validateGhostRelease,
    compareGhostVersions, ghostPackageFromReleases } from './GhostRepositoryCore';

export const ghostSmelterStatus = reactive({ error: '', latest: '', checking: false });

// Runs alongside the original suite query. A missing/addon-only feed must never
// replace, block, or roll back the suite catalog.
export async function syncGhostSmelterRepository(game: Game): Promise<void> {
    ghostSmelterStatus.checking = true;
    try {
        const options = { timeout: 8000, params: { ghost_check: Date.now().toString(36) + Math.random().toString(36).slice(2) },
            headers: { 'Cache-Control': 'no-cache, no-store, max-age=0', Pragma: 'no-cache' } };
        const [latestResult, catalogResult] = await Promise.allSettled([
            axios.get(GHOST_ORIGIN + '/smelter-release.json', options),
            axios.get(GHOST_ORIGIN + '/smelter-releases.json', options),
        ]);
        let checked = catalogResult.status === 'fulfilled' ? normalizeGhostCatalog(catalogResult.value.data) : [];
        const latest = latestResult.status === 'fulfilled' ? validateGhostRelease(latestResult.value.data) : undefined;
        if (latest) {
            const same = checked.find(r => r.version === latest.version);
            if (same && (same.sha256 !== latest.sha256 || same.bytes !== latest.bytes)) throw new Error('Ghost smelter feed conflict');
            checked = normalizeGhostCatalog([...checked.filter(r => r.version !== latest.version), latest]);
        }
        if (!checked.length) throw new Error('Ghost smelter feed unavailable');
        const cached = await Db.getPackageFromDatabase(game.internalFolderName, GHOST_SMELTER_PACKAGE).catch(() => undefined);
        if (cached && catalogResult.status === 'rejected') {
            const older = cached.versions.map((v: any) => validateGhostRelease({ version: v.version_number,
                date: v.date_created.slice(0, 10), file: `downloads/Ghost-GhostSmelterControl-${v.version_number}.zip`,
                bytes: v.file_size, sha256: v.ghost_sha256, notes: v.description, dependencies: v.dependencies }));
            checked = normalizeGhostCatalog([...checked, ...older.filter(r => !checked.some(n => n.version === r.version))].slice(0, 100));
        }
        if (cached?.versions.length && compareGhostVersions(cached.versions[0]!.version_number, checked[0]!.version) > 0)
            throw new Error('Smelter feed is older than the saved catalog');
        await Db.upsertPackageListChunk(game.internalFolderName, [ghostPackageFromReleases(checked, GHOST_SMELTER_PACKAGE)]);
        ghostSmelterStatus.latest = checked[0]!.version;
        ghostSmelterStatus.error = latest ? '' : '제련 모드의 최신 배포 조회에 실패하여 저장된 목록을 사용합니다.';
    } catch {
        ghostSmelterStatus.error = '제련 모드 배포에 연결하지 못했습니다. 저장된 버전은 유지합니다.';
    } finally { ghostSmelterStatus.checking = false; }
}

