test('separate smelter feed joins the catalog without modifying suite package', async () => {
    const suite = { ...release('1.0.40'), file: 'downloads/Ghost-GhostValheimSuite-1.0.40.zip' };
    await Db.upsertPackageListChunk('Valheim', [ghostPackageFromReleases([suite])]);
    vi.spyOn(axios, 'get').mockImplementation(async (url: any) => ({ data: String(url).endsWith('/smelter-release.json') ? release() : [release()] }));
    await syncGhostSmelterRepository(game);
    expect(await Db.getPackageVersionNumbers('Valheim', GHOST_SMELTER_PACKAGE)).toEqual(['1.0.0']);
    expect(await Db.getPackageVersionNumbers('Valheim', GHOST_PACKAGE)).toEqual(['1.0.40']);
    const p = await Db.getPackageFromDatabase('Valheim', GHOST_SMELTER_PACKAGE);
    expect(p.versions[0]!.download_url).toBe(ghostSmelterDownloadUrl('1.0.0'));
});
