test('offline, conflicting, wrong-path and older feeds preserve validated local catalog', async () => {
    await Db.upsertPackageListChunk('Valheim', [ghostPackageFromReleases([release('1.0.1'), release()], GHOST_SMELTER_PACKAGE)]);
    for (const mode of ['offline', 'conflict', 'path', 'older']) {
        vi.spyOn(axios, 'get').mockImplementation(async (url: any) => {
            if (mode === 'offline') throw Error('offline');
            const latest = mode === 'older' ? release() : release('1.0.1');
            if (mode === 'path') latest.file = 'downloads/Ghost-GhostValheimSuite-1.0.1.zip';
            return { data: String(url).endsWith('/smelter-release.json') ? latest
                : [{ ...latest, ...(mode === 'conflict' ? { sha256: 'b'.repeat(64) } : {}) }] };
        });
        await syncGhostSmelterRepository(game);
        expect(await Db.getPackageVersionNumbers('Valheim', GHOST_SMELTER_PACKAGE)).toEqual(['1.0.1', '1.0.0']);
