test('second-mod payload is checked by actual installer size, origin and SHA256 guard', async () => {
    vi.stubGlobal('crypto', webcrypto);
    try {
        const payload = new Uint8Array([1, 2, 3]).buffer;
        const r = { ...release(), sha256: createHash('sha256').update(new Uint8Array(payload)).digest('hex') };
        await Db.upsertPackageListChunk('Valheim', [ghostPackageFromReleases([r], GHOST_SMELTER_PACKAGE)]);
        const combos = await Db.getCombosByDependencyStrings(game, [GHOST_SMELTER_PACKAGE + '-1.0.0']);
        await expect(verifyGhostPayload(combos[0]!, payload)).resolves.toBeUndefined();
        await expect(verifyGhostPayload(combos[0]!, new Uint8Array([1, 2, 4]).buffer)).rejects.toThrow('SHA-256');
        await expect(verifyGhostPayload(combos[0]!, new Uint8Array([1, 2]).buffer)).rejects.toThrow();
    } finally { vi.unstubAllGlobals(); }
});
